}

package main

import "fmt"

func classify(score int) string {
	if v := score / 10; v >= 9 {
		return "A"
	} else if v >= 7 {
		return "B"
	} else {
		return "C"
	}
}

func main() {
	for _, s := range []int{95, 72, 50} {
		fmt.Printf("%d -> %s\n", s, classify(s))
	}
}

package main

import "fmt"

func bucket(n int) string {
	switch {
	case n < 0:
		return "negative"
	case n == 0:
		return "zero"
	case n < 10:
		return "small"
	default:
		return "large"
	}
}

func main() {
	for _, n := range []int{-1, 0, 5, 99} {
		fmt.Printf("%d=%s\n", n, bucket(n))
	}
}

package main

import "fmt"

func describe(v any) string {
	switch x := v.(type) {
	case int:
		return fmt.Sprintf("int:%d", x)
	case string:
		return fmt.Sprintf("string:%s", x)
	case bool:
		return fmt.Sprintf("bool:%t", x)
	default:
		return "unknown"
	}
}

func main() {
	for _, v := range []any{1, "go", true, 3.14} {
		fmt.Println(describe(v))
	}
}

