// T082 context 一：取消与传播。
//
// context.WithCancel 派生一个可取消的上下文；调用 cancel() 会关闭 Done()
// 返回的 channel，所有监听它的下游任务据此提前退出。本示例启动一个循环
// 任务，取消后通过 channel 汇报"已退出"，主流程等待该信号，结果确定。
package main

import (
	"context"
	"fmt"
)

func main() {
	ctx, cancel := context.WithCancel(context.Background())

	done := make(chan struct{})
	go func() {
		// 任务循环：每次迭代检查是否被取消。
		for i := 0; ; i++ {
			select {
			case <-ctx.Done():
				// 被取消：报告原因并退出。
				fmt.Println("worker stopped:", ctx.Err())
				close(done)
				return
			default:
				// 正常继续（这里不做事，仅计数到某个点后自行取消）。
				if i == 3 {
					fmt.Println("worker reached checkpoint, requesting cancel")
					cancel()
				}
			}
		}
	}()

	// 等待 worker 确认退出。不依赖睡眠/时间，用 channel 做同步。
	<-done
	fmt.Println("main observed worker exit")

	// 传播：派生的子 context 也会随父取消而 Done。
	parent, pcancel := context.WithCancel(context.Background())
	child, ccancel := context.WithCancel(parent)
	pcancel()
	<-child.Done()
	fmt.Println("child canceled by parent:", child.Err())
	ccancel()
}

// T083 context 二：超时与截止时间。
//
// WithTimeout 在指定时长后自动取消，超时后 ctx.Err() 返回
// context.DeadlineExceeded。本示例只断言「超时是否发生」这类语义结果，
// 不让任何分支依赖墙钟或调度竞速：慢任务用永不就绪的 channel 等待超时，
// 快/未取消路径用一个不会被取消的 context 顺序验证。
package main

import (
	"context"
	"errors"
	"fmt"
)

func main() {
	// 场景一：任务永不完成 -> 一定超时。选择超时分支是确定性的。
	slowCtx, slowCancel := context.WithTimeout(context.Background(), 1)
	defer slowCancel()
	select {
	case <-neverReady():
		fmt.Println("slow: task finished")
	case <-slowCtx.Done():
		fmt.Println("slow: deadline exceeded =", errors.Is(slowCtx.Err(), context.DeadlineExceeded))
	}

	// 场景二：未取消的 context -> 顺序返回结果，不依赖时间竞速。
	okCtx, okCancel := context.WithCancel(context.Background())
	defer okCancel()
	result, err := doWork(okCtx)
	fmt.Println("ok: result =", result, "err =", err)

	// 场景三：显式取消后立即返回 context.Canceled。
	canceledCtx, cancel := context.WithCancel(context.Background())
	cancel()
	_, err = doWork(canceledCtx)
	fmt.Println("canceled: err is context canceled =", errors.Is(err, context.Canceled))
}

// doWork 在 ctx 已取消时返回错误，否则顺序返回结果。
func doWork(ctx context.Context) (int, error) {
	select {
	case <-ctx.Done():
		return 0, ctx.Err()
	default:
		return 42, nil
	}
}

// neverReady 返回一个永不就绪的 channel，用于确定性地触发超时分支。
func neverReady() <-chan struct{} { return make(chan struct{}) }

// T084 并发模式：worker pool 与 errgroup 式编排。
//
// 用固定数量的 worker 从任务 channel 取活、把结果写入结果 channel，
// 是经典的 worker pool。本示例不引入第三方 errgroup，而是用标准库
// WaitGroup + error channel 实现等价"并行执行并在有错时返回"的编排。
// 结果收集后排序输出，保证确定性。
package main

import (
	"errors"
	"fmt"
	"sort"
	"sync"
)

func main() {
	jobs := make([]int, 20)
	for i := range jobs {
		jobs[i] = i + 1
	}

	results, err := runPool(jobs, 4, func(n int) (int, error) {
		if n == 13 {
			return 0, errors.New("unlucky 13")
		}
		return n * n, nil
	})
	if err != nil {
		fmt.Println("pool error:", err)
	}

	// 排序后输出，消除 worker 完成顺序的不确定性。
	sort.Ints(results)
	fmt.Println("squares (sorted):", results)
}

// runPool 用 workers 个 goroutine 处理 jobs，返回排序无关的成功结果切片。
// 语义上等价于 errgroup：任一任务出错即记录；这里采用"收集首个错误"策略。
func runPool(jobs []int, workers int, fn func(int) (int, error)) ([]int, error) {
	in := make(chan int)
	out := make(chan int)
	errCh := make(chan error, 1)

	var wg sync.WaitGroup
	wg.Add(workers)
	for w := 0; w < workers; w++ {
		go func() {
			defer wg.Done()
			for n := range in {
				v, err := fn(n)
				if err != nil {
					select {
					case errCh <- err: // 只记录第一个错误
					default:
					}
					continue
				}
				out <- v
			}
		}()
	}

	// 喂任务。
	go func() {
		for _, n := range jobs {
			in <- n
		}
		close(in)
	}()

	// 收结果。
	var results []int
	collectDone := make(chan struct{})
	go func() {
		for v := range out {
			results = append(results, v)
		}
		close(collectDone)
	}()

	wg.Wait()
	close(out)
	<-collectDone

	select {
	case err := <-errCh:
		return results, err
	default:
		return results, nil
	}
}

// T085 io.Reader / io.Writer 抽象。
//
// io.Reader 只有一个 Read([]byte) 方法，io.Writer 只有一个 Write([]byte) 方法。
// 任何实现了它们的东西都能互相组合：文件、网络、内存缓冲、字符串……
// 本示例把字符串当 Reader、把 bytes.Buffer 当 Writer，用 io.Copy 搬运，
// 从而无需知道底层到底是什么。
package main

import (
	"bytes"
	"fmt"
	"io"
	"strings"
)

func main() {
	// strings.Reader 实现了 io.Reader。
	var r io.Reader = strings.NewReader("hello, io.Reader")

	// bytes.Buffer 实现了 io.Writer。
	var w io.Writer = &bytes.Buffer{}

	// io.Copy 只依赖这两个接口，不关心具体类型。
	n, err := io.Copy(w, r)
	fmt.Println("copied bytes:", n, "err:", err)
	fmt.Println("buffer content:", w.(*bytes.Buffer).String())

	// 自定义 Reader：把固定字节重复 n 次。
	rr := &repeatReader{data: []byte("ab"), times: 3}
	out, _ := io.ReadAll(rr)
	fmt.Println("custom reader:", string(out))
}

// repeatReader 是自定义 io.Reader，演示只要实现 Read 就能被 io 工具使用。
type repeatReader struct {
	data  []byte
	times int
	pos   int
}

func (r *repeatReader) Read(p []byte) (int, error) {
	// 计算还剩多少重复次数。
	if r.pos >= len(r.data)*r.times {
		return 0, io.EOF
	}
	n := copy(p, r.data[r.pos%len(r.data):])
	r.pos += n
	return n, nil
}

// T086 文件读写：os.Open/Create 与缓冲。
//
// 本示例在系统临时目录里创建文件，写入内容后读回，最后清理。
// 使用 os.CreateTemp 得到唯一路径，避免污染工作目录；
// 关键习惯：写后 Close 才能保证数据落盘，读前也用 defer Close。
package main

import (
	"fmt"
	"os"
	"path/filepath"
)

func main() {
	dir, err := os.MkdirTemp("", "qfli-t086-")
	if err != nil {
		panic(err)
	}
	// defer 保证函数退出时清理整个临时目录。
	defer os.RemoveAll(dir)

	path := filepath.Join(dir, "notes.txt")

	// 写入：os.Create 会截断或新建文件。
	f, err := os.Create(path)
	if err != nil {
		panic(err)
	}
	content := "line one\nline two\n"
	if _, err := f.WriteString(content); err != nil {
		f.Close()
		panic(err)
	}
	// Close 必须在再次打开前调用，否则缓冲/句柄状态不一致。
	if err := f.Close(); err != nil {
		panic(err)
	}

	// 读取：os.ReadFile 一次性读入。
	data, err := os.ReadFile(path)
	if err != nil {
		panic(err)
	}
	fmt.Println("read back:")
	fmt.Print(string(data))

	// 校验字节数，作为确定性断言。
	info, _ := os.Stat(path)
	fmt.Println("size matches:", int(info.Size()) == len(content))
}

// T087 bufio：按行/按词扫描与缓冲写。
//
// bufio.Scanner 把 Reader 包装成"按行/按词"的迭代器，内部用缓冲减少系统调用。
// 注意默认单行上限约 64KB，超长行需要 Buffer() 调大上限。
// 本示例按行与按词两种方式扫描同一段文本，统计结果确定。
package main

import (
	"bufio"
	"fmt"
	"strings"
)

func main() {
	const text = "go is fun\nbufio scans lines\nand words too\n"

	// 按行扫描。
	lineScan := bufio.NewScanner(strings.NewReader(text))
	lines := 0
	for lineScan.Scan() {
		lines++
		fmt.Printf("line %d: %s\n", lines, lineScan.Text())
	}
	fmt.Println("total lines:", lines)

	// 按词扫描：用 ScanWords 切分。
	wordScan := bufio.NewScanner(strings.NewReader(text))
	wordScan.Split(bufio.ScanWords)
	words := 0
	for wordScan.Scan() {
		words++
	}
	fmt.Println("total words:", words)
}

// T088 目录遍历与文件信息。
//
// os.ReadDir 返回目录条目并按文件名排序，因此输出天然确定。
// 用 FileInfo 可拿到名称、大小、是否为目录等元数据。
//
// 注意：目录条目的 Size() 是**文件系统相关**的值（Linux 上常见 4096，
// Windows 上常见 0），不能作为确定性输出。因此本示例对目录只打印类型，
// 只对普通文件打印大小——这样跨平台输出一致。
package main

import (
	"fmt"
	"os"
	"path/filepath"
)

func main() {
	dir, err := os.MkdirTemp("", "qfli-t088-")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)

	// 建两个文件和一个子目录，用于演示“是否目录”的判断。
	mustWrite(filepath.Join(dir, "alpha.txt"), "a")
	mustWrite(filepath.Join(dir, "beta.txt"), "bb")
	if err := os.Mkdir(filepath.Join(dir, "sub"), 0o755); err != nil {
		panic(err)
	}

	entries, err := os.ReadDir(dir)
	if err != nil {
		panic(err)
	}
	// ReadDir 已按名字排序：alpha.txt, beta.txt, sub。
	for _, e := range entries {
		if e.IsDir() {
			// 目录不打印易变的 size。
			fmt.Printf("%-10s dir\n", e.Name())
			continue
		}
		info, err := e.Info()
		if err != nil {
			panic(err)
		}
		fmt.Printf("%-10s file size=%d\n", e.Name(), info.Size())
	}
}

func mustWrite(path, content string) {
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		panic(err)
	}
}

// T089 JSON 一：Marshal/Unmarshal 基础。
//
// encoding/json 在 Go 值与 JSON 文本之间转换。Marshal 把结构体转成 JSON
// 字节；Unmarshal 把 JSON 解析回结构体。结构体字段必须是导出的（首字母大写）
// 才会被编码，否则会被忽略。
package main

import (
	"encoding/json"
	"fmt"
)

// Profile 是要被编解码的结构体。字段都导出。
type Profile struct {
	Name    string   `json:"name"`
	Age     int      `json:"age"`
	Hobbies []string `json:"hobbies"`
}

func main() {
	p := Profile{
		Name:    "gopher",
		Age:     15,
		Hobbies: []string{"coding", "reading"},
	}

	// 结构体 -> JSON。
	data, err := json.Marshal(p)
	if err != nil {
		panic(err)
	}
	fmt.Println("marshal:", string(data))

	// JSON -> 结构体。
	var back Profile
	if err := json.Unmarshal(data, &back); err != nil {
		panic(err)
	}
	fmt.Println("unmarshal name:", back.Name)
	fmt.Println("unmarshal age:", back.Age)
	fmt.Println("unmarshal hobbies:", back.Hobbies)

	// 往返一致：编码再解码应得到相等结构（切片需用元素比较）。
	again, _ := json.Marshal(back)
	fmt.Println("round-trip stable:", string(again) == string(data))
}

// T090 JSON 二：struct tag、omitempty 与自定义名称。
//
// struct tag 控制 JSON 字段名、是否省略空值、是否忽略字段等。
// omitempty 在字段为零值时省略该键；"-" 表示完全忽略；自定义名字改变键名。
// 本示例展示三种行为，输出确定。
package main

import (
	"encoding/json"
	"fmt"
	"strings"
)

// Account 演示 tag 的常见用法。
type Account struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Password string `json:"-"`                    // 永不序列化
	Email    string `json:"email,omitempty"`      // 空则省略
	Nickname string `json:"nick_name,omitempty"`  // 改名 + 空则省略
	Balance  int    `json:"balance"`              // 零值也保留
}

func main() {
	a := Account{ID: 7, Name: "alice"}
	data, _ := json.Marshal(a)
	fmt.Println("minimal:", string(data))

	// 填入可选字段后，omitempty 的键出现。
	a.Email = "alice@example.com"
	a.Nickname = "ali"
	a.Balance = 100
	data2, _ := json.Marshal(a)
	fmt.Println("filled: ", string(data2))

	// Password 设为非空也永远不会出现在 JSON 中。
	a.Password = "secret"
	data3, _ := json.Marshal(a)
	fmt.Println("password hidden:", !strings.Contains(string(data3), "secret"))
}

// T091 JSON 三：流式 Decoder/Encoder 与未知字段。
//
// json.Decoder 可以连续解码一个流中的多个 JSON 值（如 NDJSON），
// 比 Unmarshal 更适合逐步读取；Decoder.DisallowUnknownFields 会让
// 未知字段报错，便于严格校验。
// 本示例演示：连续解码多个对象、忽略未知字段（默认行为）。
package main

import (
	"encoding/json"
	"fmt"
	"strings"
)

// Event 是流中的一个事件对象。
type Event struct {
	Type string `json:"type"`
	Code int    `json:"code"`
}

func main() {
	// 一个"流"里包含三个 JSON 对象，其中第二个还有未知字段 extra。
	stream := `{"type":"start","code":1}
{"type":"tick","code":2,"extra":"ignored"}
{"type":"stop","code":3}`

	dec := json.NewDecoder(strings.NewReader(stream))
	count := 0
	for dec.More() {
		var e Event
		// 默认忽略未知字段，因此第二行能成功解码。
		if err := dec.Decode(&e); err != nil {
			panic(err)
		}
		count++
		fmt.Printf("event %d: type=%s code=%d\n", count, e.Type, e.Code)
	}
	fmt.Println("decoded events:", count)

	// 严格模式：未知字段会报错。
	strict := json.NewDecoder(strings.NewReader(`{"type":"x","code":9,"bogus":true}`))
	strict.DisallowUnknownFields()
	var e Event
	err := strict.Decode(&e)
	fmt.Println("strict decode rejected unknown field:", err != nil)
}

// T092 时间一：time.Time、Duration 与格式化。
//
// Go 的时间格式化不使用格式串（如 yyyy-MM-dd），而是用一个"参考时间"
// 2006-01-02 15:04:05 作为布局。本示例使用固定时区与固定时间，
// 因此输出完全确定，不依赖当前时刻。
package main

import (
	"fmt"
	"time"
)

func main() {
	// 固定时区 UTC，构造一个确定的时间点。
	loc := time.UTC
	t := time.Date(2026, 10, 12, 14, 30, 45, 0, loc)

	// 参考布局 "2006-01-02 15:04:05"。
	fmt.Println("formatted:", t.Format("2006-01-02 15:04:05"))
	fmt.Println("date only:", t.Format("2006-01-02"))
	fmt.Println("RFC3339:  ", t.Format(time.RFC3339))

	// 解析：布局必须与实际字符串一致，否则报错。
	parsed, err := time.ParseInLocation("2006-01-02 15:04:05", "2020-01-02 03:04:05", loc)
	if err != nil {
		panic(err)
	}
	fmt.Println("parsed:", parsed.Format(time.RFC3339))

	// Duration 运算：纯时长加减，与墙钟无关。
	d := 90 * time.Minute
	fmt.Println("duration:", d)
	fmt.Println("duration minutes:", d.Minutes())

	later := t.Add(d)
	diff := later.Sub(t)
	fmt.Println("add 90m ->", later.Format("15:04:05"))
	fmt.Println("diff == 90m:", diff == d)
}

// T093 时间二：定时器、Ticker 与单调时钟。
//
// time.Timer 触发一次；time.Ticker 周期性触发。二者都基于单调时钟，
// 不受系统墙钟调整影响。本示例只断言"触发的次数"，不比较实际耗时，
// 因此输出确定、可离线验证。
package main

import (
	"fmt"
	"time"
)

func main() {
	// Timer：一次性。等待其通道被触发。
	timer := time.NewTimer(1 * time.Millisecond)
	<-timer.C
	fmt.Println("timer fired once")

	// Ticker：周期性。计数到 3 次后停止。
	ticker := time.NewTicker(1 * time.Millisecond)
	defer ticker.Stop()

	count := 0
	for range ticker.C {
		count++
		if count == 3 {
			break
		}
	}
	fmt.Println("ticker fired count:", count)

	// 停止后的 Ticker 不再触发（用 select+default 非阻塞探测，结果确定）。
	ticker.Stop()
	select {
	case <-ticker.C:
		fmt.Println("unexpected tick after stop")
	default:
		fmt.Println("no tick after stop")
	}

	// 演示 Now 的单调性：两次调用取差值为正（不断言具体数值）。
	start := time.Now()
	elapsed := time.Since(start)
	fmt.Println("elapsed is non-negative:", elapsed >= 0)
}

// T094 正则一：regexp 匹配与子匹配。
//
// regexp.MustCompile 在正则非法时 panic，适合包级常量；FindStringSubmatch
// 返回整体匹配与各捕获组。本示例从固定字符串中提取结构化字段，输出确定。
package main

import (
	"fmt"
	"regexp"
)

func main() {
	// 匹配形如 "key=value" 的日志片段，捕获 key 与 value。
	re := regexp.MustCompile(`(\w+)=(\w+)`)

	line := "user=alice role=admin active=true"
	// 找出所有匹配。
	all := re.FindAllStringSubmatch(line, -1)
	fmt.Println("matches:", len(all))
	for _, m := range all {
		// m[0] 是整体，m[1]/m[2] 是捕获组。
		fmt.Printf("  key=%-8s value=%s\n", m[1], m[2])
	}

	// 单个匹配。
	one := re.FindStringSubmatch("host=node1")
	fmt.Println("single full match:", one[0])
	fmt.Println("single group1:", one[1])
	fmt.Println("single group2:", one[2])

	// 无匹配时返回 nil；这里做存在性判断。
	fmt.Println("no match is nil:", re.FindStringSubmatch("nokv") == nil)
}

// T095 正则二：替换、分割与预编译复用。
//
// ReplaceAllStringFunc 允许用函数动态决定每个匹配的替换值；
// Split 用正则切分；预编译（MustCompile 到包级变量）避免重复编译。
// 本示例输出确定。
package main

import (
	"fmt"
	"regexp"
)

// 包级预编译：只编译一次，整个程序复用。
var (
	numberRe = regexp.MustCompile(`\d+`)
	spaceRe  = regexp.MustCompile(`\s+`)
)

func main() {
	src := "a1 b22 c333"

	// 条件替换：把每个数字 n 替换为 n*2 的字符串。
	doubled := numberRe.ReplaceAllStringFunc(src, func(m string) string {
		// m 一定是数字串，这里手工解析以避免引入 strconv 干扰阅读。
		n := 0
		for _, r := range m {
			n = n*10 + int(r-'0')
		}
		return fmt.Sprint(n * 2)
	})
	fmt.Println("doubled:", doubled)

	// 简单替换：把所有数字替换为 "#"。
	masked := numberRe.ReplaceAllString(src, "#")
	fmt.Println("masked: ", masked)

	// 用连续空白分割。
	parts := spaceRe.Split("one   two\tthree  four", -1)
	fmt.Println("split count:", len(parts))
	for i, p := range parts {
		fmt.Printf("  [%d]=%s\n", i, p)
	}
}

// T096 文本模板 text/template。
//
// text/template 用 {{.Field}} 占位符渲染结构化数据。模板可包含
// 条件 {{if}}、循环 {{range}}。本示例把渲染结果写入 bytes.Buffer，
// 再统一打印——不直接依赖 os.Stdout 捕获，输出因此确定、易测试。
package main

import (
