// T098 哈希与校验：crypto/sha256 与 encoding/hex。
//
// SHA-256 把任意字节映射为固定的 32 字节摘要。本示例对固定输入计算摘要，
// 并与公开已知测试向量对照（"abc" 的 SHA-256 是广为人知的标准向量），
// 因此结果确定、可离线核对。
package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
)

func main() {
	// 已知测试向量：SHA-256("abc")
	// = ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad
	const want = "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"

	sum := sha256.Sum256([]byte("abc"))
	got := hex.EncodeToString(sum[:])
	fmt.Println("sha256(abc) =", got)
	fmt.Println("matches known vector:", got == want)

	// 空串的已知向量。
	empty := sha256.Sum256(nil)
	fmt.Println("sha256(\"\") length bytes:", len(empty))
	fmt.Println("sha256(\"\") hex:", hex.EncodeToString(empty[:]))

	// 流式哈希：对分块写入的内容求和，结果与一次性相同。
	h := sha256.New()
	_, _ = h.Write([]byte("a"))
	_, _ = h.Write([]byte("bc"))
	streamed := hex.EncodeToString(h.Sum(nil))
	fmt.Println("streamed == one-shot:", streamed == got)

	// hex 解码往返。
	decoded, err := hex.DecodeString(got)
	fmt.Println("decoded bytes:", len(decoded), "err:", err)
}

// T099 net/http 客户端：GET 与响应处理。
//
// http.Client 发起请求、读取响应。为避免联网，本示例用
// net/http/httptest 起一个本地测试服务器，Client 请求它并读取 body。
//
// test-package 工程例子，不能一键导入。完整结构：
//   httpclient/
//   ├── go.mod        // module httpclient\n\ngo 1.27
//   └── client_test.go // 本文件
// 运行（官方 SDK）：go test ./...
// 移动端 Yaegi 对 net 未实测，desktop only。
package httpclient

import (
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestClientGet(t *testing.T) {
	// 本地测试服务器，不访问外网。
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			t.Errorf("method = %s, want GET", r.Method)
		}
		w.WriteHeader(http.StatusOK)
		_, _ = io.WriteString(w, "hello from server")
	}))
	defer srv.Close()

	resp, err := http.Get(srv.URL)
	if err != nil {
		t.Fatalf("GET failed: %v", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want 200", resp.StatusCode)
	}
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatalf("read body: %v", err)
	}
	if string(body) != "hello from server" {
		t.Fatalf("body = %q", string(body))
	}
}

// T100 net/http 服务端：Handler 与路由。
//
// http.ServeMux 把路径映射到 Handler。用 httptest.NewRecorder 可以在不
// 真正监听端口的情况下直接调用 Handler 并检查响应，因此测试离线且确定。
//
// test-package 工程例子，不能一键导入。完整结构：
//   httpserver/
//   ├── go.mod         // module httpserver\n\ngo 1.27
//   └── server_test.go // 本文件
// 运行：go test ./...   desktop only。
package httpserver

import (
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
)

// NewMux 构造路由表，便于测试直接复用。
func NewMux() *http.ServeMux {
	mux := http.NewServeMux()
	mux.HandleFunc("/hello", func(w http.ResponseWriter, r *http.Request) {
		_, _ = io.WriteString(w, "hello")
	})
	mux.HandleFunc("/bye", func(w http.ResponseWriter, r *http.Request) {
		_, _ = io.WriteString(w, "bye")
	})
	return mux
}

func TestRoutes(t *testing.T) {
	mux := NewMux()
	cases := []struct {
		path string
		want string
	}{
		{"/hello", "hello"},
		{"/bye", "bye"},
	}
	for _, c := range cases {
		req := httptest.NewRequest(http.MethodGet, c.path, nil)
		rec := httptest.NewRecorder()
		mux.ServeHTTP(rec, req)
		if rec.Code != http.StatusOK {
			t.Fatalf("%s status = %d", c.path, rec.Code)
		}
		if got := rec.Body.String(); got != c.want {
			t.Fatalf("%s body = %q, want %q", c.path, got, c.want)
		}
	}
}

// T101 请求与响应：Method、Header、状态码。
//
// Handler 可读取 r.Method / r.Header 并据此分支；用 w.WriteHeader 设置
// 状态码。方法不匹配时返回 405 Method Not Allowed 是常见约定。
//
// test-package 工程例子，不能一键导入。完整结构：
//   httpmethod/
//   ├── go.mod         // module httpmethod\n\ngo 1.27
//   └── method_test.go // 本文件
// 运行：go test ./...   desktop only。
package httpmethod

import (
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
)

// handler 只接受 POST；其他方法返回 405 并带 Allow 头。
func handler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		w.Header().Set("Allow", http.MethodPost)
		w.WriteHeader(http.StatusMethodNotAllowed)
		return
	}
	// 回显自定义头。
	w.Header().Set("X-Echo", r.Header.Get("X-Token"))
	w.WriteHeader(http.StatusCreated)
	_, _ = io.WriteString(w, "created")
}

func TestMethodRouting(t *testing.T) {
	// POST：应 201。
	post := httptest.NewRequest(http.MethodPost, "/", nil)
	post.Header.Set("X-Token", "abc")
	postRec := httptest.NewRecorder()
	handler(postRec, post)
	if postRec.Code != http.StatusCreated {
		t.Fatalf("POST status = %d, want 201", postRec.Code)
	}
	if got := postRec.Header().Get("X-Echo"); got != "abc" {
		t.Fatalf("X-Echo = %q, want abc", got)
	}

	// GET：应 405 且带 Allow 头。
	get := httptest.NewRequest(http.MethodGet, "/", nil)
	getRec := httptest.NewRecorder()
	handler(getRec, get)
	if getRec.Code != http.StatusMethodNotAllowed {
		t.Fatalf("GET status = %d, want 405", getRec.Code)
	}
	if got := getRec.Header().Get("Allow"); got != http.MethodPost {
		t.Fatalf("Allow = %q, want POST", got)
	}
}

// T102 JSON API 与错误响应约定。
//
// 一个 JSON API 应统一响应结构：成功返回数据，失败返回错误码与消息，
// 并设置 Content-Type: application/json。本示例用统一 envelope 输出，
// 并测试正常与错误两条路径。
//
// test-package 工程例子，不能一键导入。完整结构：
//   httpjson/
//   ├── go.mod      // module httpjson\n\ngo 1.27
//   └── api_test.go // 本文件
// 运行：go test ./...   desktop only。
package httpjson

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
)

// Envelope 是所有响应的统一外壳。
type Envelope struct {
	OK    bool   `json:"ok"`
	Data  any    `json:"data,omitempty"`
	Error string `json:"error,omitempty"`
}

// handler 依赖查询参数 name：有则成功，无则错误。
func handler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	name := r.URL.Query().Get("name")
	if name == "" {
		w.WriteHeader(http.StatusBadRequest)
		_ = json.NewEncoder(w).Encode(Envelope{OK: false, Error: "name is required"})
		return
	}
	_ = json.NewEncoder(w).Encode(Envelope{OK: true, Data: map[string]string{"name": name}})
}

func TestJSONAPI(t *testing.T) {
	// 成功路径。
	okReq := httptest.NewRequest(http.MethodGet, "/?name=alice", nil)
	okRec := httptest.NewRecorder()
	handler(okRec, okReq)
	if okRec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200", okRec.Code)
	}
	if ct := okRec.Header().Get("Content-Type"); ct != "application/json" {
		t.Fatalf("content-type = %q", ct)
	}
	var okEnv Envelope
	if err := json.Unmarshal(okRec.Body.Bytes(), &okEnv); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if !okEnv.OK {
		t.Fatalf("ok = false, want true")
	}

	// 错误路径。
	badReq := httptest.NewRequest(http.MethodGet, "/", nil)
	badRec := httptest.NewRecorder()
	handler(badRec, badReq)
	if badRec.Code != http.StatusBadRequest {
		t.Fatalf("status = %d, want 400", badRec.Code)
	}
	var badEnv Envelope
	if err := json.Unmarshal(badRec.Body.Bytes(), &badEnv); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if badEnv.OK || badEnv.Error == "" {
		t.Fatalf("error envelope = %+v", badEnv)
	}
	var raw map[string]json.RawMessage
	_ = json.Unmarshal(badRec.Body.Bytes(), &raw)
	if _, present := raw["data"]; present {
		t.Fatal("error response must not include data")
	}
}

// T103 中间件：日志、恢复与链式组合。
//
// 中间件是"接收一个 Handler、返回一个 Handler"的函数，可在调用前后插入
// 逻辑（日志、恢复、鉴权）。多个中间件可链式包裹。本示例用中间件记录
// 请求方法并统计调用次数，用 httptest 断言链路确实被经过。
//
// test-package 工程例子，不能一键导入。完整结构：
//   httpmw/
//   ├── go.mod     // module httpmw\n\ngo 1.27
//   └── mw_test.go // 本文件
// 运行：go test ./...   desktop only。
package httpmw

import (
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
)

// Middleware 是标准中间件签名。
type Middleware func(http.Handler) http.Handler

// logging 记录每个经过的请求方法。
func logging(log *[]string) Middleware {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			*log = append(*log, r.Method+" "+r.URL.Path)
			next.ServeHTTP(w, r)
		})
	}
}

// recoverer 捕获 panic，返回 500，保证链路不崩。
func recoverer(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if rec := recover(); rec != nil {
				w.WriteHeader(http.StatusInternalServerError)
			}
		}()
		next.ServeHTTP(w, r)
	})
}

// chain 按顺序包裹：chain(h, a, b) == a(b(h))。
func chain(h http.Handler, mws ...Middleware) http.Handler {
	for i := len(mws) - 1; i >= 0; i-- {
		h = mws[i](h)
	}
	return h
}

func TestMiddlewareChain(t *testing.T) {
	var log []string

	final := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/boom" {
			panic("boom")
		}
		_, _ = io.WriteString(w, "ok")
	})
	h := chain(final, logging(&log), recoverer)

	// 正常请求。
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/ok", nil))
	if rec.Body.String() != "ok" {
		t.Fatalf("body = %q, want ok", rec.Body.String())
	}

	// panic 请求：recoverer 应返回 500。
	rec2 := httptest.NewRecorder()
	h.ServeHTTP(rec2, httptest.NewRequest(http.MethodGet, "/boom", nil))
	if rec2.Code != http.StatusInternalServerError {
		t.Fatalf("panic status = %d, want 500", rec2.Code)
	}

	// 日志中间件应记录两次，且顺序确定。
	if len(log) != 2 || log[0] != "GET /ok" || log[1] != "GET /boom" {
		t.Fatalf("log = %v", log)
	}
}

// T104 超时、重试与优雅关闭。
//
// http.Server 应设置超时避免慢连接耗尽资源；优雅关闭用
// Server.Shutdown(ctx) 等待在途请求结束。本示例用 httptest 服务器 +
// 带 Client.Timeout 的客户端演示超时，并用 Shutdown 演示优雅关闭。
// 断言只看"是否超时/是否成功关闭"，不比较具体耗时。
//
// test-package 工程例子，不能一键导入。完整结构：
//   httptimeout/
//   ├── go.mod            // module httptimeout\n\ngo 1.27
//   └── timeout_test.go   // 本文件
// 运行：go test ./...   desktop only（涉及监听/关闭）。
package httptimeout

import (
	"context"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

func TestClientTimeout(t *testing.T) {
	// 服务器故意慢于客户端超时。
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		time.Sleep(50 * time.Millisecond)
		_, _ = w.Write([]byte("late"))
	}))
	defer srv.Close()

	client := &http.Client{Timeout: 5 * time.Millisecond}
	_, err := client.Get(srv.URL)
	// 断言：必然超时（错误来自 Client.Timeout），不比较精确耗时。
	if err == nil {
		t.Fatal("expected timeout error, got nil")
	}
}

func TestGracefulShutdown(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_, _ = w.Write([]byte("ok"))
	}))

	// 正常请求成功。
	resp, err := http.Get(srv.URL)
	if err != nil {
		t.Fatalf("GET: %v", err)
	}
	resp.Body.Close()

	// 优雅关闭：给一个确定的短超时；断言关闭调用无错误。
	ctx, cancel := context.WithTimeout(context.Background(), time.Second)
	defer cancel()
	if err := srv.Config.Shutdown(ctx); err != nil {
		t.Fatalf("shutdown: %v", err)
	}
	srv.Close()
}

