// desktop only（移动端不支持 fuzz）。
package fuzztest

import (
	"fmt"
	"strconv"
	"testing"
)

// ParsePort 解析端口并校验范围。
func ParsePort(s string) (int, error) {
	n, err := strconv.Atoi(s)
	if err != nil {
		return 0, err
	}
	if n < 1 || n > 65535 {
		return 0, fmt.Errorf("port %d out of range", n)
	}
	return n, nil
}

func TestParsePortSeeds(t *testing.T) {
	cases := []struct {
		in      string
		wantErr bool
	}{
		{"80", false},
		{"65535", false},
		{"0", true},
		{"65536", true},
		{"abc", true},
	}
	for _, c := range cases {
		_, err := ParsePort(c.in)
		if (err != nil) != c.wantErr {
			t.Fatalf("ParsePort(%q) err=%v, wantErr=%v", c.in, err, c.wantErr)
		}
	}
}

// FuzzParsePort 断言不变量：成功则必在 [1,65535]，否则必有错误。
func FuzzParsePort(f *testing.F) {
	f.Add("80")
	f.Add("0")
	f.Add("65536")
	f.Add("not-a-number")
	f.Fuzz(func(t *testing.T, s string) {
		n, err := ParsePort(s)
		if err == nil && (n < 1 || n > 65535) {
			t.Fatalf("ParsePort(%q) = %d with nil error, out of range", s, n)
		}
	})
}

