type Service struct{ store Store }

// Lookup 读取 key 并在缺失时返回统一错误。
func (s *Service) Lookup(key string) (string, error) {
	v, err := s.store.Get(key)
	if err != nil {
		return "", err
	}
	return v, nil
}

// stubStore 是测试桩：用 map 提供确定数据，并可配置返回错误。
type stubStore struct {
	data map[string]string
	err  error
}

func (s stubStore) Get(key string) (string, error) {
	if s.err != nil {
		return "", s.err
	}
	v, ok := s.data[key]
	if !ok {
		return "", errors.New("not found")
	}
	return v, nil
}

func TestLookupSuccess(t *testing.T) {
	svc := &Service{store: stubStore{data: map[string]string{"a": "1"}}}
	v, err := svc.Lookup("a")
	if err != nil || v != "1" {
		t.Fatalf("Lookup(a) = %q,%v", v, err)
	}
}

func TestLookupNotFound(t *testing.T) {
	svc := &Service{store: stubStore{data: map[string]string{}}}
	if _, err := svc.Lookup("missing"); err == nil {
		t.Fatal("expected error for missing key")
	}
}

func TestLookupStoreFailure(t *testing.T) {
	sentinel := errors.New("backend down")
	svc := &Service{store: stubStore{err: sentinel}}
	_, err := svc.Lookup("a")
	if !errors.Is(err, sentinel) {
		t.Fatalf("err = %v, want sentinel", err)
	}
}

// T112 内存分配与逃逸分析。
//
// 编译器决定一个变量分配在栈还是堆上。若变量"逃逸"到函数外（被返回、
// 存入接口、被闭包长期捕获等），就分配到堆。用
//   go build -gcflags=-m
// 可查看逃逸报告。本示例给出可对比的两种写法。
//
// module-project 工程例子，不能一键导入。完整结构：
//   escapeanalyze/
//   ├── go.mod   // module escapeanalyze\n\ngo 1.27
//   └── main.go  // 本文件
// 运行（官方 SDK）：
//   go run .
//   go build -gcflags=-m .    // 查看逃逸报告
// desktop only。
package main

import "fmt"

// Point 是小的值类型。
type Point struct{ X, Y int }

// makeValue 按值返回：调用方拿到副本。
func makeValue() Point {
	p := Point{1, 2} // 可能留在栈上
	return p
}

// makePointer 返回指针：p 逃逸到堆。
func makePointer() *Point {
	p := Point{3, 4} // 逃逸：地址被返回
	return &p
}

// makeInterface 存入接口：通常逃逸（接口值在堆上）。
func makeInterface() any {
	p := Point{5, 6}
	return p
}

func main() {
	v := makeValue()
	fmt.Println("value:", v.X, v.Y)

	p := makePointer()
	fmt.Println("pointer:", p.X, p.Y)

	var a any = makeInterface()
	fmt.Println("interface:", a)

	fmt.Println("hint: `go build -gcflags=-m .` shows which variables escape to the heap")
}

// T113 剖析：pprof CPU 与内存。
//
// runtime/pprof 可在程序内采集 CPU/内存剖面；更常用的是在测试里
// `go test -cpuprofile`/`-memprofile` 生成文件，再用 go tool pprof 分析。
// 本示例提供一段可被 profile 的热点函数，并打印如何采集。
//
// module-project 工程例子，不能一键导入。完整结构：
//   pprofdemo/
//   ├── go.mod              // module pprofdemo\n\ngo 1.27
//   ├── main.go             // 本文件
//   └── pprof_test.go       // 基准，供 -cpuprofile 采集
// 运行（官方 SDK）：
//   go test -bench . -cpuprofile=cpu.out .
//   go tool pprof cpu.out
// desktop only。
package main

import "fmt"

// hot 是一个 CPU 热点：反复做整数运算。
func hot(n int) int {
	total := 0
	for i := 0; i < n; i++ {
		total += i % 7
	}
	return total
}

func main() {
	// 运行热点并打印确定结果。
	fmt.Println("hot(1000) =", hot(1000))
	fmt.Println("profile with: go test -bench . -cpuprofile=cpu.out .")
	fmt.Println("then: go tool pprof cpu.out")
}

// T114 性能优化范式：预分配、批处理、零拷贝。
//
// 常见优化：用预分配切片（make([]T, 0, n)）避免反复扩容；
// 用 strings.Builder 拼接避免多次分配；用复用缓冲避免重复分配。
// 断言策略：功能等价断言（输出正确）+ 基准只作参考，不作通过条件。
//
// test-package / benchmark 工程例子，不能一键导入。完整结构：
//   perfpatterns/
//   ├── go.mod           // module perfpatterns\n\ngo 1.27
//   └── patterns_test.go // 本文件
// 运行（官方 SDK）：
//   go test ./...
//   go test -bench . -benchmem ./...
// desktop only。
package perfpatterns

import (
	"strings"
	"testing"
)

// appendNoPrealloc 不预分配，靠 append 扩容。
func appendNoPrealloc(n int) []int {
	var s []int
	for i := 0; i < n; i++ {
		s = append(s, i)
	}
	return s
}

// appendPrealloc 预分配容量，减少扩容次数。
func appendPrealloc(n int) []int {
	s := make([]int, 0, n)
	for i := 0; i < n; i++ {
		s = append(s, i)
	}
	return s
}

// joinConcat 用 + 拼接。
func joinConcat(parts []string) string {
	out := ""
	for _, p := range parts {
		out += p
	}
	return out
}

// joinBuilder 用 strings.Builder 拼接。
func joinBuilder(parts []string) string {
	var b strings.Builder
	for _, p := range parts {
		b.WriteString(p)
	}
	return b.String()
}

func TestEquivalence(t *testing.T) {
	a := appendNoPrealloc(10)
	b := appendPrealloc(10)
	if len(a) != len(b) {
		t.Fatalf("lengths differ: %d vs %d", len(a), len(b))
	}
	for i := range a {
		if a[i] != b[i] {
			t.Fatalf("element %d differs", i)
		}
	}
	parts := []string{"a", "b", "c"}
	if joinConcat(parts) != joinBuilder(parts) {
		t.Fatal("join results differ")
	}
}

func BenchmarkAppendNoPrealloc(b *testing.B) {
	b.ReportAllocs()
	for i := 0; i < b.N; i++ {
		_ = appendNoPrealloc(256)
	}
}

func BenchmarkAppendPrealloc(b *testing.B) {
	b.ReportAllocs()
	for i := 0; i < b.N; i++ {
		_ = appendPrealloc(256)
	}
}

