// T116 日志与可观测性基线：log/slog。
//
// log/slog（Go 1.21+）提供结构化日志：键值对可被机器检索。
// 可设置级别（Info/Warn/Error），并选择 Text 或 JSON handler。
//
// 为让输出确定且可被任何运行环境捕获，本示例把日志写入 bytes.Buffer
// （而非直接写 os.Stdout），并用 ReplaceAttr 去掉默认的时间戳字段——
// 日志时间依赖运行时刻，不能作为固定输出。
package main

import (
	"bytes"
	"fmt"
	"log/slog"
)

// dropTime 删除 slog 默认的 time 属性，使输出与运行时刻无关。
func dropTime(_ []string, a slog.Attr) slog.Attr {
	if a.Key == slog.TimeKey {
		return slog.Attr{} // 空 Attr 会被忽略
	}
	return a
}

func main() {
	var buf bytes.Buffer
	opts := &slog.HandlerOptions{Level: slog.LevelInfo, ReplaceAttr: dropTime}

	// Text handler，级别 Info；输出写入内存缓冲。
	logger := slog.New(slog.NewTextHandler(&buf, opts))

	logger.Info("server starting", "addr", "127.0.0.1:8080", "pid", 1)
	logger.With("component", "db").Warn("slow query", "ms", 120)
	logger.Debug("this is filtered out") // 低于 Info，被过滤

	// JSON handler，级别 Error；同一缓冲区继续追加。
	jsonLogger := slog.New(slog.NewJSONHandler(&buf, &slog.HandlerOptions{
		Level:       slog.LevelError,
		ReplaceAttr: dropTime,
	}))
	jsonLogger.Error("failed to connect", "host", "db1")

	logger.Info("shutdown complete")

	// 一次性打印全部结构化日志，输出确定。
	fmt.Print(buf.String())
}

// T117 配置、标志与环境变量。
//
// flag 解析命令行参数；环境变量常用于容器/CI 注入配置。
// 常见优先级：命令行标志优先于环境变量，环境变量优先于默认值。
// 本示例构造确定参数并打印生效配置，输出确定（不读真实环境）。
package main

import (
	"flag"
	"fmt"
	"os"
)

// config 是最终生效的配置。
type config struct {
	Addr  string
	Level string
	Port  int
}

// loadConfig 依次从默认值、环境变量、命令行标志解析配置。
func loadConfig(args []string, getenv func(string) string) (config, error) {
	c := config{Addr: "127.0.0.1", Level: "info", Port: 8080}

	// 环境变量层。
	if v := getenv("APP_ADDR"); v != "" {
		c.Addr = v
	}
	if v := getenv("APP_LEVEL"); v != "" {
		c.Level = v
	}

	// 命令行标志层（优先级最高）。
	fs := flag.NewFlagSet("demo", flag.ContinueOnError)
	addr := fs.String("addr", c.Addr, "listen address")
	level := fs.String("level", c.Level, "log level")
	port := fs.Int("port", c.Port, "listen port")
	if err := fs.Parse(args); err != nil {
		return config{}, err
	}
	c.Addr, c.Level, c.Port = *addr, *level, *port
	return c, nil
}

func main() {
	// 模拟环境变量：通过注入的 getenv 获得确定性。
	env := map[string]string{"APP_ADDR": "10.0.0.1", "APP_LEVEL": "warn"}
	getenv := func(k string) string { return env[k] }

	// 仅带命令行标志覆盖（应覆盖 env 的 addr）。
	c, err := loadConfig([]string{"-addr", "192.168.1.5", "-port", "9000"}, getenv)
	if err != nil {
		panic(err)
	}
	fmt.Printf("addr=%s level=%s port=%d\n", c.Addr, c.Level, c.Port)

	// 不带标志时，环境变量生效。
	c2, _ := loadConfig(nil, getenv)
	fmt.Printf("addr=%s level=%s port=%d\n", c2.Addr, c2.Level, c2.Port)

	// 无 env、无标志时，默认值生效。
	c3, _ := loadConfig(nil, func(string) string { return "" })
	fmt.Printf("addr=%s level=%s port=%d\n", c3.Addr, c3.Level, c3.Port)

	_ = os.Getenv // 说明真实环境变量读法；此处为确定性不直接使用。
}

// T118 综合项目一：命令行待办清单（CLI + JSON 持久化）。
//
// 整合：命令分发、JSON 持久化、错误处理。待办项存为 JSON 文件，
// 增/删/列/完成操作后落盘，重载后状态一致。
//
// module-project 工程例子，不能一键导入。完整结构：
//   todoapp/
//   ├── go.mod        // module todoapp\n\ngo 1.27
//   ├── main.go       // 本文件：CLI 入口
//   ├── store.go      // 文件存储
//   └── store_test.go // 端到端测试
// 运行（官方 SDK）：
//   go run . add "learn go"
//   go run . list
//   go test ./...
// desktop only（文件系统 + go test）。
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
)

// Item 是一条待办。
type Item struct {
	ID   int    `json:"id"`
	Text string `json:"text"`
	Done bool   `json:"done"`
}

// Store 是待办存储。
type Store struct {
	path  string
	items []Item
}

// Load 从文件加载；文件不存在时返回空存储。
func Load(path string) (*Store, error) {
	s := &Store{path: path}
	data, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return s, nil
	}
	if err != nil {
		return nil, err
	}
	if err := json.Unmarshal(data, &s.items); err != nil {
		return nil, fmt.Errorf("decode %s: %w", path, err)
	}
	return s, nil
}

// Save 原子落盘：先写临时文件再改名，避免半写状态。
func (s *Store) Save() error {
	if err := os.MkdirAll(filepath.Dir(s.path), 0o755); err != nil {
		return err
	}
	data, err := json.MarshalIndent(s.items, "", "  ")
	if err != nil {
		return err
	}
	tmp := s.path + ".tmp"
	if err := os.WriteFile(tmp, data, 0o644); err != nil {
		return err
	}
	return os.Rename(tmp, s.path)
}

// Add 追加一条并返回其 id。
func (s *Store) Add(text string) int {
	id := 1
	for _, it := range s.items {
		if it.ID >= id {
			id = it.ID + 1
		}
	}
	s.items = append(s.items, Item{ID: id, Text: text})
	return id
}

// Complete 标记完成；找不到返回错误。
func (s *Store) Complete(id int) error {
	for i := range s.items {
		if s.items[i].ID == id {
			s.items[i].Done = true
			return nil
		}
	}
	return fmt.Errorf("item %d not found", id)
}

// Items 返回按 id 排序的副本，保证输出确定。
func (s *Store) Items() []Item {
	out := append([]Item(nil), s.items...)
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

func main() {
	// 演示：用临时目录中的固定文件完成一轮增改查并重载。
	dir, err := os.MkdirTemp("", "qfli-t118-")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)
	path := filepath.Join(dir, "todo.json")

	st, err := Load(path)
	if err != nil {
		panic(err)
	}
	st.Add("learn go")
	st.Add("write tests")
	if err := st.Complete(1); err != nil {
		panic(err)
	}
	if err := st.Save(); err != nil {
		panic(err)
	}

	// 重载并打印，证明持久化一致。
	reloaded, err := Load(path)
	if err != nil {
		panic(err)
	}
	for _, it := range reloaded.Items() {
		status := "todo"
		if it.Done {
			status = "done"
		}
		fmt.Printf("%d [%s] %s\n", it.ID, status, it.Text)
	}
}

// T119 综合项目二：并发词频统计器（worker pool + IO）。
//
// 整合：worker pool、文件/字符串 IO、结果聚合。多个 worker 并发统计
// 若干文本的词频，最后按词排序输出，因此结果与串行一致且确定。
//
// module-project 工程例子，不能一键导入。完整结构：
//   wordfreq/
//   ├── go.mod          // module wordfreq\n\ngo 1.27
//   ├── main.go         // 本文件
//   └── freq_test.go    // 端到端测试（含串行/并发一致性）
// 运行（官方 SDK）：
//   go run .
//   go test ./...
// desktop only（并发 + 文件）。
package main

import (
	"fmt"
	"sort"
	"strings"
	"sync"
)

// countWords 串行统计一段文本的词频。
func countWords(text string) map[string]int {
	counts := make(map[string]int)
	for _, w := range strings.Fields(strings.ToLower(text)) {
		counts[w]++
	}
	return counts
}

// merge 把一个局部计数并入全局计数。
func merge(dst, src map[string]int) {
	for k, v := range src {
		dst[k] += v
	}
}

// CountParallel 用 workers 个 goroutine 并发统计多段文本。
func CountParallel(texts []string, workers int) map[string]int {
	if workers < 1 {
		workers = 1
	}
	jobs := make(chan string)
	partials := make(chan map[string]int)

	var wg sync.WaitGroup
	wg.Add(workers)
	for i := 0; i < workers; i++ {
		go func() {
			defer wg.Done()
			for text := range jobs {
				partials <- countWords(text)
			}
		}()
	}

	go func() {
		for _, t := range texts {
			jobs <- t
		}
		close(jobs)
	}()

	go func() {
		wg.Wait()
		close(partials)
	}()

	total := make(map[string]int)
	for p := range partials {
		merge(total, p)
	}
	return total
}

// sortedKeys 返回排序后的键，保证输出确定。
func sortedKeys(m map[string]int) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func main() {
	texts := []string{
		"go go gopher",
		"gopher runs go",
		"go test",
	}

	serial := make(map[string]int)
	for _, t := range texts {
		merge(serial, countWords(t))
	}

	parallel := CountParallel(texts, 3)

	// 并发结果必须与串行完全一致。
	fmt.Println("parallel matches serial:", sameCounts(serial, parallel))

	for _, k := range sortedKeys(parallel) {
		fmt.Printf("%-8s %d\n", k, parallel[k])
	}
}

func sameCounts(a, b map[string]int) bool {
	if len(a) != len(b) {
		return false
	}
	for k, v := range a {
		if b[k] != v {
			return false
		}
	}
	return true
}

// T120 综合项目三：极简 HTTP 服务（JSON API + 中间件 + 测试）。
//
// 整合：net/http 路由、JSON 响应、中间件、超时设置与 httptest 测试。
// 服务提供 /health 与 /api/time；中间件记录请求。
//
// module-project 工程例子，不能一键导入。完整结构：
//   miniapi/
//   ├── go.mod       // module miniapi\n\ngo 1.27
//   ├── main.go      // 本文件：路由、中间件、服务器配置
//   └── api_test.go  // httptest 端到端测试（真正断言的地方）
// 运行（官方 SDK）：
//   go test ./...     // 主要验证方式（httptest，离线）
//   go run .          // 构造 handler 并说明如何监听
// desktop only（net 监听 + go test）。
package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"time"
)

// response 是统一响应结构。
type response struct {
	Status string `json:"status"`
	Value  string `json:"value,omitempty"`
	Error  string `json:"error,omitempty"`
}

// logging 中间件：记录方法与路径到切片（便于测试断言）。
func logging(log *[]string, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		*log = append(*log, r.Method+" "+r.URL.Path)
		next.ServeHTTP(w, r)
	})
}

// NewHandler 构造路由与中间件链。now 注入固定时间以保证响应确定。
func NewHandler(now func() time.Time, log *[]string) http.Handler {
	mux := http.NewServeMux()

	mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, http.StatusOK, response{Status: "ok"})
	})

	mux.HandleFunc("/api/time", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			writeJSON(w, http.StatusMethodNotAllowed, response{Status: "error", Error: "GET only"})
			return
		}
		writeJSON(w, http.StatusOK, response{
			Status: "ok",
			Value:  now().Format(time.RFC3339),
		})
	})

	return logging(log, mux)
}

func writeJSON(w http.ResponseWriter, code int, v response) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(v)
}

func main() {
	fixed := func() time.Time { return time.Date(2026, 10, 12, 14, 0, 0, 0, time.UTC) }
	var log []string

	srv := &http.Server{
		Addr:         "127.0.0.1:8080",
		Handler:      NewHandler(fixed, &log),
