def shortest_path(graph, a, b):
    import collections
    q = collections.deque((a,), 100)
    parent = {a: None}
    while q:
        node = q.popleft()
        if node == b:
            break
        for nb in graph[node]:
            if nb not in parent:
                parent[nb] = node
                q.append(nb)
    if b not in parent:
        return None
    path = []
    cur = b
    while cur is not None:
        path.append(cur)
        cur = parent[cur]
    return path[::-1]

