def count_hits_slow(words, stopwords):
    # 每个词都线性扫描停用词列表：O(len(words) * len(stopwords))
    hits = 0
    in_list = []
    for w in words:
        if w in stopwords:
            hits += 1
            in_list.append(w)
    return hits, in_list


def count_hits_fast(words, stopwords):
    stop = set(stopwords)
    hits = 0
    in_set = []
    for w in words:
        if w in stop:
            hits += 1
            in_set.append(w)
    return hits, in_set


