class Game:
    def __init__(self):
        self.rooms = {
            "hall": {"desc": "hall", "items": ["key"],
                     "exits": {"north": "library"}},
            "library": {"desc": "library", "items": ["book"],
                        "exits": {"south": "hall", "east": "vault"}},
            "vault": {"desc": "vault", "items": ["gold"], "exits": {}},
        }
        self.current = "hall"
        self.bag = []
        self.done = False

    def handle(self, command):
        parts = command.split()
        verb = parts[0]
        room = self.rooms[self.current]
        if verb == "look":
            return "%s: %s" % (room["desc"], ",".join(room["items"]) or "empty")
        if verb == "take" and len(parts) == 2:
            item = parts[1]
            if item in room["items"]:
                room["items"].remove(item)
                self.bag.append(item)
                return "took " + item
            return "no " + item
        if verb == "go" and len(parts) == 2:
            direction = parts[1]
            target = room["exits"].get(direction)
            if target is None:
                return "blocked"
            if target == "vault" and "key" not in self.bag:
                return "locked"
            self.current = target
            return "moved to " + target
        if verb == "win":
            if self.current == "vault" and "gold" in self.bag:
                self.done = True
                return "YOU WIN"
            return "not yet"
        return "unknown"


