def zeros(rows, cols):
    return [[0] * cols for _ in range(rows)]


def transpose(matrix):
    rows = len(matrix)
    cols = len(matrix[0])
    result = zeros(cols, rows)
    for i in range(rows):
        for j in range(cols):
            result[j][i] = matrix[i][j]
    return result


def matmul(a, b):
    n, m = len(a), len(a[0])
    m2, p = len(b), len(b[0])
    if m != m2:
        raise ValueError("shape %dx%d vs %dx%d" % (n, m, m2, p))
    result = zeros(n, p)
    for i in range(n):
        for j in range(p):
            total = 0
            for k in range(m):
                total += a[i][k] * b[k][j]
            result[i][j] = total
    return result


def det2(matrix):
    return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]


