def matadd(a, b):
    if len(a) != len(b) or len(a[0]) != len(b[0]):
        raise ValueError("shape mismatch")
    return [[a[i][j] + b[i][j] for j in range(len(a[0]))]
            for i in range(len(a))]

def det(m):
    n = len(m)
    if n == 1:
        return m[0][0]
    if n == 2:
        return det2(m)
    total = 0
    for j in range(n):
        minor = [row[:j] + row[j+1:] for row in m[1:]]
        total += ((-1) ** j) * m[0][j] * det(minor)
    return total

